// src/model-controls/effort.css
var effort_default = '/* Adapted from zanwei/claude-model-selector (MIT). See LICENSE. */\n\n.ccd-effort {\n  --effort-accent: var(--ccd-effort-color-1);\n  --effort-text: var(--ccd-effort-color-3);\n  --effort-text-strong: var(--ccd-effort-color-4);\n  --effort-muted: var(--ccd-effort-color-5);\n  --effort-track: var(--ccd-effort-color-6);\n  --effort-track-fill: var(--ccd-effort-color-7);\n  --effort-progress: 0;\n  --effort-thumb-w: 16px;\n  --effort-thumb-h: 20px;\n  --effort-track-pad: 0px;\n  --effort-track-radius: 6px;\n  --effort-surface: var(--ccd-effort-color-8);\n  --effort-outline: var(--ccd-effort-color-9);\n  --ease-decay: cubic-bezier(0.2, 0, 0, 1);\n  display: block;\n  width: min(220px, calc(100vw - 24px));\n  max-width: 100%;\n  color: var(--effort-text);\n  font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;\n  font-size: 12px;\n  line-height: 1.35;\n  font-synthesis: none;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n.ccd-effort *, .ccd-effort *::before, .ccd-effort *::after {\n  box-sizing: border-box;\n}\n\n.ccd-effort button, .ccd-effort input {\n  font: inherit;\n}\n\n.ccd-effort .panel {\n  position: absolute;\n  z-index: 4;\n  right: 0;\n  bottom: 3.25rem;\n  width: 100%;\n  padding: 12px;\n  border: 1px solid var(--effort-outline);\n  border-radius: 10px;\n  background: var(--effort-surface);\n  box-shadow:\n    0 1px 2px var(--ccd-effort-color-11),\n    0 4px 10px var(--ccd-effort-color-12),\n    0 12px 28px var(--ccd-effort-color-13);\n  opacity: 1;\n  transform: translateY(0);\n  transition-property: opacity, transform;\n  transition-duration: 120ms;\n  transition-timing-function: ease-in;\n}\n\n.ccd-effort .header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  min-height: 20px;\n  gap: 8px;\n}\n\n.ccd-effort .title {\n  display: flex;\n  align-items: baseline;\n  min-width: 0;\n  color: var(--effort-text);\n  font-size: 13px;\n  font-weight: 400;\n  line-height: 1.3;\n  letter-spacing: -0.01em;\n  text-wrap: balance;\n}\n\n.ccd-effort .level-stage {\n  position: relative;\n  display: inline-block;\n  height: 1.3em;\n  margin-left: 8px;\n  color: var(--effort-text-strong);\n  line-height: inherit;\n  vertical-align: baseline;\n}\n\n.ccd-effort .level-stage > span {\n  position: absolute;\n  top: 0;\n  left: 0;\n  line-height: inherit;\n  white-space: nowrap;\n  transform-origin: left center;\n}\n\n.ccd-effort .level-current {\n  opacity: 1;\n  transform: translateY(0);\n  filter: blur(0);\n  transition-property: opacity, transform, filter, color;\n  transition-duration: 180ms;\n  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);\n}\n\n.ccd-effort .level-current.is-preparing {\n  opacity: 0;\n  transform: translateY(var(--label-enter-y, 3px));\n  filter: blur(2px);\n  transition-duration: 0ms;\n  transition-delay: 0ms;\n}\n\n.ccd-effort .level-outgoing {\n  opacity: 1;\n  transform: translateY(0);\n  filter: blur(0);\n  pointer-events: none;\n  transition-property: opacity, transform, filter;\n  transition-duration: 180ms;\n  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);\n}\n\n.ccd-effort .level-outgoing.is-exiting {\n  opacity: 0;\n  transform: translateY(var(--label-exit-y, -3px));\n  filter: blur(2px);\n}\n\n.ccd-effort[data-ultra] .level-current {\n  color: var(--effort-accent);\n}\n\n.ccd-effort .help-wrap {\n  position: relative;\n  flex: 0 0 auto;\n}\n\n.ccd-effort .help-button {\n  position: relative;\n  display: grid;\n  width: 20px;\n  height: 20px;\n  margin: 0;\n  padding: 2px;\n  place-items: center;\n  border: 0;\n  border-radius: 6px;\n  background: transparent;\n  color: var(--effort-muted);\n  cursor: help;\n  transition-property: color, background-color, scale;\n  transition-duration: 150ms;\n  transition-timing-function: ease-out;\n}\n\n.ccd-effort .help-button:hover {\n  color: var(--ccd-effort-color-14);\n  background: var(--ccd-effort-color-15);\n}\n\n.ccd-effort .help-button:active {\n  scale: 0.96;\n}\n\n.ccd-effort .help-button:focus-visible {\n  outline: 2px solid color-mix(in srgb, var(--effort-accent) 35%, transparent);\n  outline-offset: 2px;\n}\n\n.ccd-effort .help-button svg {\n  width: 14px;\n  height: 14px;\n}\n\n.ccd-effort .tooltip {\n  position: absolute;\n  z-index: 8;\n  top: auto;\n  bottom: calc(100% + 6px);\n  right: 0;\n  width: min(220px, calc(100vw - 24px));\n  padding: 10px 12px;\n  border: 1px solid var(--ccd-effort-color-16);\n  border-radius: 0.5rem;\n  background: var(--ccd-effort-color-17);\n  box-shadow:\n    0 2px 5px var(--ccd-effort-color-18),\n    0 8px 18px var(--ccd-effort-color-18);\n  color: var(--ccd-effort-color-19);\n  font-size: 12px;\n  font-weight: 450;\n  line-height: 1.35;\n  text-wrap: pretty;\n  opacity: 0;\n  visibility: hidden;\n  transform: translateY(-2px);\n  transition-property: opacity, transform, visibility;\n  transition-duration: 120ms;\n  transition-timing-function: ease-in;\n}\n\n.ccd-effort .help-wrap:hover .tooltip,\n.ccd-effort .help-button:focus-visible + .tooltip,\n.ccd-effort .help-wrap[data-tip-open] .tooltip {\n  opacity: 1;\n  visibility: visible;\n  transform: translateY(0);\n  transition-timing-function: ease-out;\n}\n\n.ccd-effort .axis {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 20px;\n  color: var(--effort-muted);\n  font-size: 12px;\n  font-weight: 400;\n  line-height: 1.3;\n  letter-spacing: -0.01em;\n}\n\n.ccd-effort .track-shell {\n  position: relative;\n  height: 32px;\n  margin-top: 2px;\n}\n\n.ccd-effort .track {\n  position: absolute;\n  inset: 6px 0;\n  overflow: hidden;\n  border-radius: var(--effort-track-radius);\n  background-color: var(--effort-track);\n}\n\n.ccd-effort .track-fill {\n  position: absolute;\n  z-index: 0;\n  top: 0;\n  bottom: 0;\n  left: 0;\n  width: calc(\n    (100% - (var(--effort-track-pad) * 2) - var(--effort-thumb-w))\n      * var(--effort-progress, 0)\n    + var(--effort-track-pad) + (var(--effort-thumb-w) * 0.5)\n  );\n  border-radius: var(--effort-track-radius) 0 0 var(--effort-track-radius);\n  background: var(--effort-track-fill);\n  pointer-events: none;\n  transition-property: opacity;\n  transition-duration: 200ms;\n  transition-timing-function: var(--ease-decay);\n}\n\n.ccd-effort[data-ultra] .track-fill {\n  opacity: 0;\n}\n\n.ccd-effort .track::before {\n  content: "";\n  position: absolute;\n  z-index: 0;\n  inset: 0;\n  border-radius: inherit;\n  background: linear-gradient(\n    90deg,\n    var(--ccd-effort-color-21) 0%,\n    var(--ccd-effort-color-22) 18%,\n    var(--ccd-effort-color-23) 32%,\n    var(--ccd-effort-color-24) 48%,\n    var(--ccd-effort-color-25) 68%,\n    var(--ccd-effort-color-26) 82%,\n    var(--ccd-effort-color-27) 100%\n  );\n  opacity: 0;\n  transition-property: opacity;\n  transition-duration: 340ms;\n  transition-timing-function: ease-in;\n}\n\n.ccd-effort[data-ultra] .track::before {\n  opacity: 1;\n}\n\n.ccd-effort .ultra-fallback,\n.ccd-effort .pixel-field {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n  opacity: 0;\n  transition-property: opacity;\n  transition-duration: 200ms;\n  transition-timing-function: var(--ease-decay);\n}\n\n.ccd-effort .ultra-fallback {\n  background: linear-gradient(\n    90deg,\n    var(--ccd-effort-color-21) 0%,\n    var(--ccd-effort-color-22) 18%,\n    var(--ccd-effort-color-23) 32%,\n    var(--ccd-effort-color-28) 48%,\n    var(--ccd-effort-color-29) 68%,\n    var(--ccd-effort-color-30) 82%,\n    var(--ccd-effort-color-31) 100%\n  );\n}\n\n.ccd-effort[data-ultra] .pixel-field {\n  opacity: 1;\n}\n\n.ccd-effort .ticks {\n  position: absolute;\n  z-index: 1;\n  inset: 0 calc(var(--effort-track-pad) + var(--effort-thumb-w) * 0.5);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  pointer-events: none;\n}\n\n.ccd-effort .tick {\n  width: 3px;\n  height: 3px;\n  border-radius: 999px;\n  background: var(--ccd-effort-color-32);\n  opacity: 0.82;\n  transition-property: opacity;\n  transition-duration: 180ms;\n  transition-timing-function: var(--ease-decay);\n}\n\n.ccd-effort[data-ultra] .tick {\n  opacity: 0;\n}\n\n.ccd-effort .tick.is-default {\n  height: 9px;\n}\n\n.ccd-effort .default-marker-row {\n  height: 16px;\n  color: var(--effort-muted);\n  line-height: 16px;\n  text-align: center;\n}\n\n.ccd-effort .default-marker {\n  transition: color 150ms ease-out;\n}\n\n.ccd-effort .default-marker.is-selected {\n  color: var(--ccd-text);\n}\n\n.ccd-effort .range {\n  position: absolute;\n  z-index: 3;\n  inset: 0 var(--effort-track-pad);\n  width: calc(100% - var(--effort-track-pad) * 2);\n  height: 100%;\n  margin: 0;\n  appearance: none;\n  -webkit-appearance: none;\n  border: 0;\n  outline: 0;\n  background: transparent;\n  cursor: ew-resize;\n  touch-action: none;\n}\n\n.ccd-effort .range::-webkit-slider-runnable-track {\n  height: var(--effort-thumb-h);\n  border: 0;\n  background: transparent;\n}\n\n.ccd-effort .range::-webkit-slider-thumb {\n  width: var(--effort-thumb-w);\n  height: var(--effort-thumb-h);\n  margin-top: 0;\n  appearance: none;\n  -webkit-appearance: none;\n  border: 1px solid var(--ccd-effort-color-33);\n  border-radius: 6px;\n  background: var(--ccd-effort-color-19);\n  box-shadow:\n    0 1px 2px var(--ccd-effort-color-34),\n    0 4px 10px var(--ccd-effort-color-35);\n  cursor: ew-resize;\n  transition-property: transform;\n  transition-duration: 150ms;\n  transition-timing-function: ease-out;\n}\n\n.ccd-effort .range::-moz-range-track {\n  height: var(--effort-thumb-h);\n  border: 0;\n  background: transparent;\n}\n\n.ccd-effort .range::-moz-range-progress {\n  background: transparent;\n}\n\n.ccd-effort .range::-moz-range-thumb {\n  width: var(--effort-thumb-w);\n  height: var(--effort-thumb-h);\n  border: 1px solid var(--ccd-effort-color-33);\n  border-radius: 6px;\n  background: var(--ccd-effort-color-19);\n  box-shadow:\n    0 1px 2px var(--ccd-effort-color-34),\n    0 4px 10px var(--ccd-effort-color-35);\n  cursor: ew-resize;\n  transition-property: transform;\n  transition-duration: 150ms;\n  transition-timing-function: ease-out;\n}\n\n.ccd-effort .range:focus-visible::-webkit-slider-thumb {\n  box-shadow:\n    0 0 0 3px color-mix(in srgb, var(--effort-accent) 30%, transparent),\n    0 1px 2px var(--ccd-effort-color-34),\n    0 4px 10px var(--ccd-effort-color-35);\n}\n\n.ccd-effort .range:focus-visible::-moz-range-thumb {\n  box-shadow:\n    0 0 0 3px color-mix(in srgb, var(--effort-accent) 30%, transparent),\n    0 1px 2px var(--ccd-effort-color-34),\n    0 4px 10px var(--ccd-effort-color-35);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ccd-effort .level-current,\n  .ccd-effort .level-outgoing,\n  .ccd-effort .panel,\n  .ccd-effort .track::before,\n  .ccd-effort .track-fill,\n  .ccd-effort .default-marker,\n  .ccd-effort .range::-webkit-slider-thumb,\n  .ccd-effort .range::-moz-range-thumb,\n  .ccd-effort .help-button,\n  .ccd-effort .tooltip {\n    transition-duration: 0.001ms;\n  }\n\n  .ccd-effort[data-ultra] .ultra-fallback {\n    opacity: 1;\n  }\n\n  .ccd-effort .pixel-field {\n    display: none;\n  }\n}\n\n.ccd-effort .panel { position: static; width: 100%; }\n.ccd-effort { position: fixed; z-index: 1000; margin: 0; padding: 0; border: 0; background: transparent; overflow: visible; }\n.ccd-effort .level-stage::after {\n  content: attr(data-longest);\n  visibility: hidden;\n  pointer-events: none;\n}\n.ccd-effort .selection-error { margin-top: 8px; color: var(--ccd-text-secondary); font-size: 12px; overflow-wrap: anywhere; }\n';

// src/tokens.css
var tokens_default = "/* Tokens adapted from zkforge/dsh-claude-desktop-theme (MIT). */\nhtml[data-dsh-ocean-skin] {\n  --ccd-effort-color-1: #8c73c9;\n  --ccd-effort-color-2: #a17ec2;\n  --ccd-effort-color-3: #898782;\n  --ccd-effort-color-4: #000000;\n  --ccd-effort-color-5: #898782;\n  --ccd-effort-color-6: #e6e6e6;\n  --ccd-effort-color-7: #bababa;\n  --ccd-effort-color-8: #ffffff;\n  --ccd-effort-color-9: #d9d9d9;\n  --ccd-effort-color-10: #2788d6;\n  --ccd-effort-color-11: rgba(62, 56, 50, 0.05);\n  --ccd-effort-color-12: rgba(62, 56, 50, 0.04);\n  --ccd-effort-color-13: rgba(62, 56, 50, 0.06);\n  --ccd-effort-color-14: #74706d;\n  --ccd-effort-color-15: rgba(82, 76, 70, 0.055);\n  --ccd-effort-color-16: rgba(76, 70, 65, 0.1);\n  --ccd-effort-color-17: #34312f;\n  --ccd-effort-color-18: rgba(35, 31, 29, 0.12);\n  --ccd-effort-color-19: #fff;\n  --ccd-effort-color-20: rgba(70, 64, 59, 0.035);\n  --ccd-effort-color-21: #eeebe9;\n  --ccd-effort-color-22: #ece9e7;\n  --ccd-effort-color-23: #e2dce3;\n  --ccd-effort-color-24: #d9d0df;\n  --ccd-effort-color-25: #d0c1da;\n  --ccd-effort-color-26: #cdbcd9;\n  --ccd-effort-color-27: #cbbad8;\n  --ccd-effort-color-28: #d5cadc;\n  --ccd-effort-color-29: #c8b5d4;\n  --ccd-effort-color-30: #bda6cc;\n  --ccd-effort-color-31: #b59bc6;\n  --ccd-effort-color-32: rgba(0, 0, 0, 0.29);\n  --ccd-effort-color-33: rgba(0, 0, 0, 0.15);\n  --ccd-effort-color-34: rgba(62, 56, 50, 0.08);\n  --ccd-effort-color-35: rgba(62, 56, 50, 0.055);\n  --ccd-effort-pixel-leftColor: 210, 206, 214;\n  --ccd-effort-pixel-deepViolet: 156, 120, 192;\n  --ccd-effort-pixel-deepMid: 156, 132, 192;\n  --ccd-effort-pixel-midPurple: 168, 144, 204;\n  --ccd-effort-pixel-softMid: 168, 156, 204;\n  --ccd-effort-pixel-softLilac: 180, 168, 204;\n  --ccd-effort-pixel-paleCool: 192, 180, 204;\n  --ccd-effort-pixel-highlightColor: 216, 204, 228;\n  --ccd-effort-pixel-peakColor: 232, 224, 242;\n  --ccd-effort-shadow: 0 1px 2px rgba(62, 56, 50, .05), 0 4px 10px rgba(62, 56, 50, .04), 0 12px 28px rgba(62, 56, 50, .06);\n  --ccd-chip-height: 20px;\n  --ccd-chip-radius: 6px;\n  --ccd-chip-padding-inline: 7px;\n  --ccd-cluster-gap: 6px;\n  --ccd-card: #ffffff;\n  --ccd-hover: #f0f0ee;\n  --ccd-border: #e3e3e1;\n  --ccd-border-soft: #ebebe9;\n  --ccd-text: #1f1f1d;\n  --ccd-text-secondary: #6f6f6a;\n  --ccd-text-placeholder: #89877f;\n  --ccd-accent: #4b76ce;\n  --ccd-text-strong: #000000; --ccd-font-ui: inherit; --ccd-model-max-width: 45cqw;\n}\nhtml[data-dsh-ocean-skin] body[data-ds-dark-theme] {\n  --ccd-effort-color-1: #a48ede;\n  --ccd-effort-color-2: #b294d3;\n  --ccd-effort-color-3: #898782;\n  --ccd-effort-color-4: #eeeeee;\n  --ccd-effort-color-5: #898782;\n  --ccd-effort-color-6: #373736;\n  --ccd-effort-color-7: #7d7d7c;\n  --ccd-effort-color-8: #20201f;\n  --ccd-effort-color-9: rgba(255, 255, 255, 0.1);\n  --ccd-effort-color-10: #4d93f8;\n  --ccd-effort-color-11: rgba(0, 0, 0, 0.45);\n  --ccd-effort-color-12: rgba(0, 0, 0, 0.35);\n  --ccd-effort-color-13: rgba(0, 0, 0, 0.45);\n  --ccd-effort-color-14: #b7b2aa;\n  --ccd-effort-color-15: rgba(255, 255, 255, 0.06);\n  --ccd-effort-color-16: rgba(255, 255, 255, 0.14);\n  --ccd-effort-color-17: #3a3936;\n  --ccd-effort-color-18: rgba(0, 0, 0, 0.5);\n  --ccd-effort-color-19: #ffffff;\n  --ccd-effort-color-20: rgba(255, 255, 255, 0.04);\n  --ccd-effort-color-21: #34332f;\n  --ccd-effort-color-22: #373430;\n  --ccd-effort-color-23: #3e3943;\n  --ccd-effort-color-24: #463e51;\n  --ccd-effort-color-25: #4f4560;\n  --ccd-effort-color-26: #57496a;\n  --ccd-effort-color-27: #5c4d71;\n  --ccd-effort-color-28: #524667;\n  --ccd-effort-color-29: #63527c;\n  --ccd-effort-color-30: #6e5989;\n  --ccd-effort-color-31: #786096;\n  --ccd-effort-color-32: rgba(255, 255, 255, 0.305);\n  --ccd-effort-color-33: rgba(255, 255, 255, 0.16);\n  --ccd-effort-color-34: rgba(0, 0, 0, 0.4);\n  --ccd-effort-color-35: rgba(0, 0, 0, 0.35);\n  --ccd-effort-pixel-leftColor: 92, 88, 98;\n  --ccd-effort-pixel-deepViolet: 150, 116, 196;\n  --ccd-effort-pixel-deepMid: 150, 128, 196;\n  --ccd-effort-pixel-midPurple: 162, 140, 204;\n  --ccd-effort-pixel-softMid: 162, 152, 204;\n  --ccd-effort-pixel-softLilac: 174, 164, 206;\n  --ccd-effort-pixel-paleCool: 184, 174, 206;\n  --ccd-effort-pixel-highlightColor: 200, 188, 224;\n  --ccd-effort-pixel-peakColor: 214, 204, 236;\n  --ccd-effort-shadow: 0 1px 2px rgba(0, 0, 0, .4), 0 4px 10px rgba(0, 0, 0, .3), 0 12px 28px rgba(0, 0, 0, .35);\n  --ccd-card: #222222;\n  --ccd-hover: #303030;\n  --ccd-border: #383838;\n  --ccd-border-soft: #303030;\n  --ccd-text: #e8e8e6;\n  --ccd-text-secondary: #b5b5ad;\n  --ccd-text-placeholder: #999991;\n  --ccd-accent: #789be3;\n  --ccd-text-strong: #ffffff;\n}\n";

// src/skin.css
var skin_default = `/* Background only: the official theme stays as is. Pictures sit in two fixed
   layers behind the app and crossfade (client.ts rotates them). The character
   sits in the left quarter of every picture, under the sidebar, so the layers
   anchor left. Official surfaces are translucent via theme tokens (client.ts). */
html[data-dsh-ocean-skin], html[data-dsh-ocean-skin] body {
  min-height: 100%;
  background: transparent;
}
html[data-dsh-ocean-skin] { background-color: #eef2fa; }
html[data-dsh-ocean-skin]:has(body[data-ds-dark-theme]) { background-color: #141312; }

.dsh-ocean-bg-layer {
  position: fixed; inset: 0; z-index: -1; pointer-events: none;
  background-size: cover; background-position: left center; background-repeat: no-repeat;
  opacity: 0; transition: opacity 2.4s ease-in-out;
}
.dsh-ocean-bg-layer[data-on] { opacity: 1; }
.dsh-ocean-bg-layer::after {
  content: ""; position: absolute; inset: 0;
  background: rgba(250, 247, 240, 0.18);
}
body[data-ds-dark-theme] .dsh-ocean-bg-layer::after { background: rgba(12, 11, 10, 0.35); }

/* Cover layers. The official UI paints --dsw-alias-bg-base on sticky headers
   and fades so that scrolled content disappears under them. With a translucent
   bg-base they (a) let the content show through and (b) stack a second tint on
   the frame's own, which darkens them into a visible band. Make them glass
   instead: no extra tint, and blur what scrolls underneath. Matched by CSS
   module local names (the hash prefix changes between builds; the name does not). */
html[data-dsh-ocean-skin] {
  --dsh-ocean-glass-blur: blur(24px) saturate(1.2);
}
html[data-dsh-ocean-skin] [class*="_pageBar"][data-natural]::before,
html[data-dsh-ocean-skin] [class*="_compactionButton"],
html[data-dsh-ocean-skin] [data-expanded] [data-open] [data-disclosure-header],
html[data-dsh-ocean-skin] [class*="_bannerWrap"] {
  background: transparent !important;
  -webkit-backdrop-filter: var(--dsh-ocean-glass-blur);
  backdrop-filter: var(--dsh-ocean-glass-blur);
}
@media (prefers-reduced-motion: reduce) {
  .dsh-ocean-bg-layer { transition: none; }
}
`;

// assets/bg-1.jpg
var bg_1_default = "data:image/jpeg;base64,";

// assets/bg-2.jpg
var bg_2_default = "data:image/jpeg;base64,";

